<?php
if(!defined('ABSPATH'))exit;
function dgs_teacher_fields(){return array('national_id'=>'کد ملی','full_name'=>'نام و نام خانوادگی','phone'=>'موبایل (خصوصی)','birth'=>'تاریخ تولد شمسی (خصوصی)','gender'=>'جنسیت (خصوصی)','address'=>'نشانی (خصوصی)','specialty'=>'درس / تخصص','grades'=>'پایه‌های تدریس (10,11,12)','teaching_years'=>'سال سابقه تدریس','education'=>'سوابق تحصیلی (هر مدرک یک خط)','experience'=>'سوابق آموزشی (هر مورد یک خط)','bio'=>'درباره استاد','skills'=>'مهارت‌ها (هر مورد یک خط)','video'=>'لینک مستقیم ویدئو MP4/WebM','portrait_id'=>'شناسه تصویر در رسانه','published'=>'انتشار عمومی: 1 یا 0');}
function dgs_teacher_data($uid){$u=get_userdata($uid);if(!$u||!dgs_edu_role($u,'dgs_teacher'))return array();$d=get_user_meta($uid,'_dgs_teacher_private',true);$d=is_array($d)?$d:array();return array_merge(array_fill_keys(array_keys(dgs_teacher_fields()),''),$d,array('full_name'=>$u->display_name,'phone'=>get_user_meta($uid,'_dgs_contact_phone',true),'national_id'=>$d['national_id']??(dgs_edu_national_id($u->user_login)?$u->user_login:''),'revision'=>get_user_meta($uid,'_dgs_teacher_revision',true)));}
function dgs_teacher_validate($raw,$uid=0){
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','دسترسی مدیریت لازم است.');
 if(!is_array($raw))return dgs_edu_error('input','اطلاعات معتبر نیست.');foreach($raw as $v)if(!is_scalar($v))return dgs_edu_error('input','اطلاعات معتبر نیست.');
 $d=array();foreach(dgs_teacher_fields() as $key=>$label){$v=(string)($raw[$key]??'');$d[$key]=in_array($key,array('education','experience','bio','skills','address'),true)?sanitize_textarea_field($v):sanitize_text_field($v);if(dgs_edu_length($d[$key])>(in_array($key,array('education','experience','bio','skills','address'),true)?5000:200))return dgs_edu_error('length','طول فیلد '.$label.' بیش از حد است.');}
 $d['national_id']=dgs_edu_digits($d['national_id']);$d['phone']=dgs_normalize_phone($d['phone']);if(!dgs_edu_national_id($d['national_id'])||!$d['phone']||dgs_edu_length($d['full_name'])<2)return dgs_edu_error('identity','نام، کد ملی معتبر و موبایل الزامی‌اند.');
 if($uid){$u=get_userdata($uid);if(!$u||!dgs_edu_role($u,'dgs_teacher')||user_can($u,'manage_options'))return dgs_edu_error('teacher','فقط حساب دبیر قابل ویرایش است.');$old=dgs_teacher_data($uid);if($old['national_id']!==''&&$old['national_id']!==$d['national_id'])return dgs_edu_error('national','کد ملی حساب قبلی قابل تغییر نیست.');$existing=username_exists($d['national_id']);if($existing&&(int)$existing!==$uid)return dgs_edu_error('duplicate','این کد ملی متعلق به حساب دیگری است.');}elseif(username_exists($d['national_id']))return dgs_edu_error('duplicate','این حساب از قبل وجود دارد؛ برای اصلاح از ویرایش دبیر استفاده کنید.');
 if(!$d['specialty'])return dgs_edu_error('specialty','درس یا تخصص دبیر را وارد کنید.');$grades=array_values(array_unique(array_filter(array_map('trim',explode(',',dgs_edu_digits(str_replace('،',',',$d['grades'])))))));if(!$grades||array_diff($grades,array('10','11','12')))return dgs_edu_error('grade','پایه‌ها را مانند 10,11,12 وارد کنید.');sort($grades);$d['grades']=implode(',',$grades);
 $years=dgs_edu_digits($d['teaching_years']);if($years!==''&&(!ctype_digit($years)||(int)$years>70))return dgs_edu_error('years','سابقه تدریس عدد صفر تا ۷۰ باشد.');$d['teaching_years']=$years;
 if($d['birth']!==''&&!dgs_record_birth($d['birth']))return dgs_edu_error('birth','تاریخ تولد شمسی معتبر وارد کنید.');if($d['birth']!==''){$parts=explode('-',str_replace('/','-',dgs_edu_digits($d['birth'])));$d['birth']=sprintf('%04d-%02d-%02d',...array_map('intval',$parts));$g=dgs_att_gregorian(...array_map('intval',$parts));if($g>wp_date('Y-m-d'))return dgs_edu_error('birth','تاریخ تولد نمی‌تواند در آینده باشد.');}
 if(!in_array($d['gender'],array('','male','female'),true))return dgs_edu_error('gender','جنسیت معتبر نیست.');
 if($d['video']!==''){if(!filter_var($d['video'],FILTER_VALIDATE_URL)||!in_array(strtolower(wp_parse_url($d['video'],PHP_URL_SCHEME)),array('http','https'),true)||!preg_match('/\.(mp4|webm)$/i',(string)wp_parse_url($d['video'],PHP_URL_PATH)))return dgs_edu_error('video','ویدئو باید لینک مستقیم HTTP/HTTPS با پسوند MP4 یا WebM باشد.');$d['video']=esc_url_raw($d['video'],array('http','https'));}
 if($d['portrait_id']!==''&&(!ctype_digit($d['portrait_id'])||!wp_attachment_is_image((int)$d['portrait_id'])||!in_array(get_post_mime_type((int)$d['portrait_id']),array('image/jpeg','image/png','image/webp'),true)))return dgs_edu_error('portrait','شناسه تصویر معتبر JPG/PNG/WebP نیست.');
 if(!in_array($d['published'],array('','0','1'),true))return dgs_edu_error('publish','انتشار فقط صفر یا یک باشد.');$d['published']=$d['published']==='1'?'1':'0';return $d;
}
function dgs_teacher_store($d,$uid=0){
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','دسترسی ندارید.');$created=false;$post_id=0;
 if(!$uid){$uid=wp_insert_user(array('user_login'=>$d['national_id'],'user_pass'=>$d['national_id'],'display_name'=>$d['full_name'],'nickname'=>$d['full_name'],'role'=>'dgs_teacher','user_email'=>''));if(is_wp_error($uid))return dgs_edu_error('create','حساب استاد ساخته نشد.');$created=true;}
 else{$result=wp_update_user(array('ID'=>$uid,'display_name'=>$d['full_name'],'nickname'=>$d['full_name']));if(is_wp_error($result))return dgs_edu_error('update','حساب به‌روز نشد.');}
 $post_id=(int)get_user_meta($uid,'_dgs_teacher_post',true);if($post_id&&(get_post_type($post_id)!=='dgs_teacher'||(int)get_post_meta($post_id,'_dgs_user_id',true)!==$uid))return dgs_edu_error('link','ارتباط رزومه معتبر نیست؛ مدیریت بررسی کند.');
 $public=array('post_type'=>'dgs_teacher','post_title'=>$d['full_name'],'post_content'=>$d['bio'],'post_excerpt'=>wp_trim_words($d['bio'],35),'post_status'=>$d['published']==='1'?'publish':'draft');if($post_id)$public['ID']=$post_id;
 $post_id=wp_insert_post(wp_slash($public),true);if(is_wp_error($post_id)||!$post_id){if($created){require_once ABSPATH.'wp-admin/includes/user.php';wp_delete_user($uid);}return dgs_edu_error('post','رزومه ذخیره نشد.');}
 foreach(array('specialty','grades','teaching_years','education','experience','skills','video') as $key)update_post_meta($post_id,'_dgs_'.$key,wp_slash($d[$key]));update_post_meta($post_id,'_dgs_group','teacher');update_post_meta($post_id,'_dgs_user_id',$uid);
 if($d['portrait_id'])set_post_thumbnail($post_id,(int)$d['portrait_id']);else delete_post_thumbnail($post_id);
 update_user_meta($uid,'_dgs_teacher_post',$post_id);update_user_meta($uid,'_dgs_teacher_private',wp_slash($d));update_user_meta($uid,'_dgs_contact_phone',$d['phone']);update_user_meta($uid,'_dgs_teacher_revision',wp_generate_uuid4());if($created)update_user_meta($uid,'_dgs_created_by',get_current_user_id());
 if(get_user_meta($uid,'_dgs_teacher_private',true)!==$d||get_user_meta($uid,'_dgs_contact_phone',true)!==$d['phone']){if($created){wp_delete_post($post_id,true);require_once ABSPATH.'wp-admin/includes/user.php';wp_delete_user($uid);}return dgs_edu_error('verify','ذخیره پرونده کامل نشد؛ دوباره بررسی کنید.');}dgs_edu_audit($created?'teacher_create':'teacher_update',$uid);if(function_exists('dgs_catalog_invalidate'))dgs_catalog_invalidate($post_id);return array('uid'=>$uid,'post'=>$post_id,'created'=>$created);
}
function dgs_teacher_import_rows($rows){
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','دسترسی ندارید.');if(!$rows||count($rows)>100)return dgs_edu_error('rows','یک تا ۱۰۰ دبیر در هر فایل مجاز است.');$ready=array();$ids=array();$cols=array_keys(dgs_teacher_fields());
 foreach($rows as $i=>$row){$d=dgs_teacher_validate(array_combine($cols,array_pad(array_slice($row,0,count($cols)),count($cols),'')));if(is_wp_error($d))return dgs_edu_error('row','ردیف '.($i+2).': '.$d->get_error_message());if(isset($ids[$d['national_id']]))return dgs_edu_error('duplicate','کد ملی تکراری در فایل: ردیف '.($i+2));$ids[$d['national_id']]=true;$ready[]=$d;}
 $made=array();foreach($ready as $d){$result=dgs_teacher_store($d);if(is_wp_error($result)){require_once ABSPATH.'wp-admin/includes/user.php';foreach($made as $item){wp_delete_post($item['post'],true);wp_delete_user($item['uid']);}return $result;}$made[]=$result;}return count($made);
}
function dgs_teacher_redirect($message,$error=false){$token=wp_generate_password(24,false,false);set_transient('dgs_edu_flash_'.get_current_user_id().'_'.$token,array('text'=>$message,'error'=>$error),120);wp_safe_redirect(add_query_arg('dg_notice',$token,dgs_school_url('education',dgs_edu_current_year(),array('school_section'=>'teaching'))),303);exit;}
function dgs_teacher_guard(){if(!current_user_can('dgs_manage_education'))wp_die('دسترسی ندارید.','',array('response'=>403));if(($_SERVER['REQUEST_METHOD']??'')!=='POST')wp_die('روش معتبر نیست.','',array('response'=>405));check_admin_referer('dgs_teacher','dgs_teacher_nonce');}
add_action('admin_post_dgs_teacher_save',function(){dgs_teacher_guard();$raw=wp_unslash($_POST);$uid=absint(is_scalar($raw['teacher_id']??null)?$raw['teacher_id']:0);$d=dgs_teacher_validate($raw,$uid);if(is_wp_error($d))dgs_teacher_redirect($d->get_error_message(),true);
 if($uid){$revision=is_string($raw['revision']??null)?$raw['revision']:'';if($revision!==get_user_meta($uid,'_dgs_teacher_revision',true))dgs_teacher_redirect('پرونده تغییر کرده است؛ صفحه را تازه کنید.',true);}
 $lock='dgs_teacher_lock_'.($uid?:$d['national_id']);if(!add_option($lock,time(),'','no')){if((int)get_option($lock)<time()-120)delete_option($lock);dgs_teacher_redirect('پرونده در حال ذخیره است؛ دوباره تلاش کنید.',true);}
 $image=0;try{if(isset($_FILES['portrait'])&&($_FILES['portrait']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$f=$_FILES['portrait'];$tmp=$f['tmp_name']??'';$info=is_string($tmp)?@getimagesize($tmp):false;if(($f['error']??1)!==0||!is_uploaded_file($tmp)||($f['size']??0)>3*1024*1024||!$info||$info[0]*$info[1]>20000000||!in_array($info['mime'],array('image/jpeg','image/png','image/webp'),true)){delete_option($lock);dgs_teacher_redirect('عکس سالم JPG/PNG/WebP تا ۳ مگابایت باشد.',true);}require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/image.php';$image=media_handle_upload('portrait',0,array(),array('test_form'=>false,'mimes'=>array('jpg|jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp')));if(is_wp_error($image)){delete_option($lock);dgs_teacher_redirect('عکس ذخیره نشد.',true);}$d['portrait_id']=(string)$image;}
 $result=dgs_teacher_store($d,$uid);if(is_wp_error($result)&&$image)wp_delete_attachment($image,true);
 }finally{delete_option($lock);}dgs_teacher_redirect(is_wp_error($result)?$result->get_error_message():($uid?'اطلاعات استاد و رزومه به‌روز شد.':'حساب استاد و پرونده کامل ساخته شد؛ نام کاربری و رمز اولیه کد ملی است.'),is_wp_error($result));});
add_action('admin_post_dgs_teacher_import',function(){dgs_teacher_guard();$f=$_FILES['teacher_xlsx']??null;if(!is_array($f)||($f['error']??1)!==0||!is_uploaded_file($f['tmp_name']??'')||($f['size']??0)>2*1024*1024||strtolower(pathinfo($f['name']??'',PATHINFO_EXTENSION))!=='xlsx')dgs_teacher_redirect('فایل XLSX تا ۲ مگابایت لازم است.',true);$rows=dgs_school_xlsx_rows($f['tmp_name'],array_keys(dgs_teacher_fields()));$result=is_wp_error($rows)?$rows:dgs_teacher_import_rows($rows);dgs_teacher_redirect(is_wp_error($result)?$result->get_error_message():dgs_fa_digits($result).' حساب استاد و پرونده ساخته شد.',is_wp_error($result));});
add_action('admin_post_dgs_teacher_template',function(){if(!current_user_can('dgs_manage_education'))wp_die('دسترسی ندارید.','',array('response'=>403));check_admin_referer('dgs_teacher_template');$bytes=dgs_school_xlsx(array(array_keys(dgs_teacher_fields())));if(is_wp_error($bytes))wp_die(esc_html($bytes->get_error_message()));nocache_headers();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="daneshgaran-teachers.xlsx"');echo $bytes;exit;});
